contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 v, address other) public {
        uint256 ownerBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 otherBefore = c.balanceOf(other); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.burn(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint256 ownerAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 otherAfter = c.balanceOf(other); if (__ESBMC_reverted()) return;
        uint256 supplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;

        uint256 sumBefore = ownerBefore + otherBefore;
        uint256 sumAfter = ownerAfter + otherAfter;

        assert(
            (!reverted && ownerBefore >= v && sumAfter + v == sumBefore && supplyAfter + v == supplyBefore)
            ||
            (reverted && sumAfter == sumBefore && supplyAfter == supplyBefore)
        );
    }
}

